@php($portal=app(\App\Services\Community::class))
<div class="activity-grid">@forelse($activities as $a)
@php($entry=collect($enrollments)->first(fn($e)=>$e['activity_id']===$a['activity_id'] && $e['status']!=='cancelled'))
<article class="activity-card"><div class="card-photo"><img src="{{ $portal->activityImage($a) }}" alt="{{ $portal->activityImageAlt($a) }}" loading="lazy" decoding="async"><span class="photo-label">{{ strtoupper($a['categories']['name'] ?? 'COMMUNITY') }}</span></div><div class="card-content"><div class="card-meta"><span class="category-pill">{{ $a['categories']['name'] ?? 'Community' }}</span>@if($entry)<span class="enrollment-state">{{ ucfirst($entry['status']) }}</span>@elseif(!in_array($a['status'],['open','full']) || !\Carbon\Carbon::parse($a['cutoff_at'])->isFuture())<span class="availability">{{ ucfirst($a['status']) }} · Registration closed</span>@elseif(isset($a['confirmed']))<span class="availability">{{ $a['capacity']-$a['confirmed'] > 0 ? ($a['capacity']-$a['confirmed']).' spots left' : 'Waitlist available' }}</span>@else<span class="availability">{{ ucfirst($a['status']) }}</span>@endif</div><h3><a href="/activities/{{ $a['activity_id'] }}">{{ $a['title'] }}</a></h3><p class="schedule">{{ \Carbon\Carbon::parse($a['start_at'])->timezone(config('app.timezone'))->format('D, M j · g:i A') }}</p><p class="venue">{{ $a['venue'] }}</p><a class="card-action" href="/activities/{{ $a['activity_id'] }}">View activity <span aria-hidden="true">→</span></a></div></article>
